#include "engine.hpp"
#include <iostream>
#include <algorithm>
using namespace uaa;
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
int main(int argc,char** argv){try{
 check(argc==3,"Expected data and temporary directory");Engine e(argv[1],argv[2]);fs::create_directories(e.userDir);
 check(e.createBase("First",50,14).ok,"Create first base");check(e.state["money"]==6500000,"First base must be free");check(e.createBase("Second",40,10).ok,"Create second base");check(e.state["money"]==5500000,"Later base price");
 int soldier=-1;for(int i=0;i<int(e.state["personnel"].size());++i)if(e.state["personnel"][i]["role"]=="soldier"){soldier=i;break;}check(soldier>=0,"Starting soldier exists");
 int armed=0,rifles=0,machineGuns=0,rockets=0;for(std::size_t i=0;i<e.state["personnel"].size();++i)if(e.state["personnel"][i]["role"]=="soldier"){auto weapon=e.soldierLoadout(i)["primaryWeapon"];check(!weapon.get<std::string>().empty(),"Every starting soldier is armed");rifles+=weapon=="rifle";machineGuns+=weapon=="machine-gun";rockets+=weapon=="rocket-launcher";check(e.loadoutWeight(e.soldierLoadout(i))<=e.soldierCapacity(i),"Assigned weapon respects carry capacity");++armed;}check(armed==8&&rifles==5&&machineGuns==2&&rockets==1,"Starting squad receives specialist heavy weapons");check(e.state["stock"]["rifle"]==3&&e.state["stock"]["machine-gun"]==0&&e.state["stock"]["rocket-launcher"]==0,"Weapons are transferred from stock without duplication");

 long long rocketScore=-1,maxRocket=-1,minGunner=1000000,maxRifle=-1;for(std::size_t i=0;i<e.state["personnel"].size();++i)if(e.state["personnel"][i]["role"]=="soldier"){const auto& p=e.state["personnel"][i];const auto& a=p["attributes"];long long rocket=2LL*p.value("missions",0)+3*a["MARKSMANSHIP"].get<int>()+2*a["STRENGTH"].get<int>()+a["STAMINA"].get<int>();long long gunner=2LL*p.value("missions",0)+a["MARKSMANSHIP"].get<int>()+2*a["STRENGTH"].get<int>()+2*a["STAMINA"].get<int>();maxRocket=std::max(maxRocket,rocket);auto weapon=e.soldierLoadout(i)["primaryWeapon"];if(weapon=="rocket-launcher")rocketScore=rocket;if(weapon=="machine-gun")minGunner=std::min(minGunner,gunner);if(weapon=="rifle")maxRifle=std::max(maxRifle,gunner);}check(rocketScore==maxRocket&&minGunner>=maxRifle,"Specialist weapons go to the most suitable available soldiers");
 auto stock=e.state["stock"].value("pistol",0);check(e.equipSoldier(soldier,"primaryWeapon","pistol").ok,"Equip pistol");check(e.state["stock"]["pistol"]==stock-1,"Assigned pistol leaves available inventory");
 check(e.equipSoldier(soldier,"primaryWeapon","").ok,"Unequip pistol");check(e.state["stock"]["pistol"]==stock,"Unequipped item returns to storage");
 auto before=e.state;check(!e.equipSoldier(soldier,"beltSlots","rocket-ammo",0).ok,"Belt rejects size three rocket");check(e.state==before,"Rejected choice is transactional");
 check(e.equipSoldier(soldier,"beltSlots","pistol-ammo",3).ok,"Belt accepts size one magazine");before=e.state;check(!e.equipSoldier(soldier,"beltSlots","pistol-ammo",4).ok,"Belt index validation");check(e.state==before,"Invalid index cannot mutate stock");
 auto packing=e.backpackPacking(Json::array({"rifle"}));check(!packing.is_null(),"Rifle rotates into five-wide backpack");check(std::count(packing.begin(),packing.end(),Json(0))==5,"Rifle occupies five cells");
 packing=e.backpackPacking(Json::array({"machine-gun","machine-gun"}));check(!packing.is_null()&&packing.size()==20,"Two heavy guns pack into twenty cells");check(e.backpackPacking(Json::array({"machine-gun","machine-gun","machine-gun"})).is_null(),"Third gun does not fit");
 e.state["stock"]["rifle"]=5;for(int i=0;i<4;++i)check(e.equipSoldier(soldier,"backpack","rifle").ok,"Four rifles fit");before=e.state;check(!e.equipSoldier(soldier,"backpack","rifle").ok,"Backpack overflow rejected");check(e.state==before,"Overflow preserves inventory");check(e.equipSoldier(soldier,"backpack","",1).ok,"Remove backpack contents");check(e.state["stock"]["rifle"]==2,"Removed backpack item returned");
 auto& helmet=e.catalog["db"]["gamesets"][0]["equipment"];for(auto& r:helmet)if(r["id"]=="combat-helmet"){auto original=r["combat"]["values"]["weight"];r["combat"]["values"]["weight"]=100;e.state["stock"]["combat-helmet"]=1;before=e.state;check(!e.equipSoldier(soldier,"helmet","combat-helmet").ok,"Combat carry limit enforced");check(e.state==before,"Overweight choice preserves state");r["combat"]["values"]["weight"]=original;break;}
 check(e.renamePerson(soldier,"ALPHA").ok,"Rename soldier");check(!e.renamePerson(soldier,"").ok,"Reject empty name");
 before=e.state;check(!e.assignCrew(0,"pilot",6).ok,"Wrong profession rejected");check(e.state==before,"Rejected crew cannot mutate aircraft");check(e.assignCrew(0,"pilot",0).ok,"Assign pilot");check(e.state["craft"][0]["crew"]["pilot"]==0,"Pilot saved");check(e.assignCrew(0,"pilot",-1).ok,"Unassign pilot");
 for(int i=6;i<12;++i)check(e.assignCrew(2,"technician",i).ok,"Assign six technicians");before=e.state;check(!e.assignCrew(2,"technician",12).ok,"Seventh technician rejected");check(e.state==before,"Crew capacity rejection preserves state");
 auto& c=e.state["craft"][0];c["fuel"]=50.;c["hull"]=90.;c["ammo"]=290;c["missiles"]=7;auto quote=e.serviceQuote(0);check(quote["cost"]==72370&&quote["hours"]==10,"HTML service quote formula");
 auto money=e.state["money"];e.state["money"]=0;before=e.state;check(!e.serviceAircraft(0).ok,"Service needs funds");check(e.state==before,"Service rejection preserves condition and funds");e.state["money"]=money;
 check(e.serviceAircraft(0).ok,"Start service");check(e.state["money"].get<long long>()==money.get<long long>()-72370,"Service charged once");before=e.state;check(!e.serviceAircraft(0).ok,"Cannot start service twice");check(e.state==before,"Duplicate service not charged");
 e.advance(9);check(e.state["craft"][0].contains("serviceReady")&&e.state["craft"][0]["fuel"]==50.,"Service takes simulated time");e.advance(1);check(!e.state["craft"][0].contains("serviceReady"),"Service completes at deadline");check(e.state["craft"][0]["fuel"]==100.&&e.state["craft"][0]["hull"]==100.&&e.state["craft"][0]["ammo"]==300&&e.state["craft"][0]["missiles"]==8,"Service restores condition and ammunition");
 e.save(1);auto saved=e.state;Engine restored(argv[1],argv[2]);check(restored.load(1).ok,"Extended save loads");auto loaded=restored.state;loaded.erase("rng");saved.erase("rng");check(saved==loaded,"Loadout and crew survive save roundtrip");
 auto invalid=readJson(e.userDir/"save-1.json");invalid["personnel"][soldier]["loadout"]["beltSlots"]=Json::array({"pistol-ammo"});writeJson(e.userDir/"save-2.json",invalid);before=restored.state;check(!restored.load(2).ok,"Malformed loadout is rejected");check(restored.state==before,"Invalid save cannot replace campaign");
 Engine legacy(argv[1],argv[2]);legacy.save(3);check(restored.load(3).ok,"Older native saves without loadouts remain compatible");
 Engine gym(argv[1],fs::path(argv[2])/"gym");gym.createBase("Gym",50,14);check(!gym.startGymTraining(soldier).ok,"Training requires a completed gym");check(gym.build(0,"gym",7,4,0).ok,"Construct gym");check(!gym.startGymTraining(soldier).ok,"Unfinished gym cannot train");gym.advance(72);gym.state["personnel"][soldier]["attributes"]["STRENGTH"]=99;auto stats=gym.state["personnel"][soldier]["attributes"];check(gym.startGymTraining(soldier).ok,"Start physical training");auto trainingState=gym.state;check(!gym.startGymTraining(soldier).ok&&gym.state==trainingState,"Duplicate training is transactional");gym.advance(24);check(gym.state["personnel"][soldier]["attributes"]==stats,"Training is not awarded early");gym.save(1);Engine trained(argv[1],fs::path(argv[2])/"gym");check(trained.load(1).ok,"Training survives save reload");trained.advance(24);for(auto key:{"STRENGTH","FITNESS","STAMINA","REACTIONS","TIME_UNITS"})check(trained.state["personnel"][soldier]["attributes"][key]==std::min(100,stats[key].get<int>()+2),"Training improves physical attributes with a cap");check(trained.state["personnel"][soldier]["attributes"]["MARKSMANSHIP"]==stats["MARKSMANSHIP"]&&!trained.state["personnel"][soldier].contains("gymTraining"),"Gym does not improve shooting and finishes once");check(trained.startGymTraining(soldier).ok&&trained.cancelGymTraining(soldier).ok,"Cancel gym training");stats=trained.state["personnel"][soldier]["attributes"];trained.advance(48);check(trained.state["personnel"][soldier]["attributes"]==stats,"Cancelled training awards no attributes");
 std::cout<<"PASS: equipment compatibility, transactional stock, 5x4 packing/rotation, carry weight, rename, crew professions/capacity, timed service, extended and legacy saves\n";return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
